arguments.command:
cd /tmp/opencode && python3 - <<'EOF'
import json
b=json.load(open("before.json")); a=json.load(open("after.json"))
for k in b:
    for r1,r2 in zip(b[k],a[k]):
        if r1!=r2:
            diffs={f:(r1[f],r2[f]) for f in r1 if r1[f]!=r2[f]}
            print(f"[{k}] {r1['description']!r} remark={r1['remark']!r} {r1['type']}")
            for f,(x,y) in diffs.items():
                print(f"      {f}: {x!r} -> {y!r}")
EOF

